declare function num(value: number): Expr<"number">;
/** Decimal literal — `Expr<"decimal">`. */
declare function dec(value: number): Expr<"decimal">;
/** Text literal — `Expr<"text">`. Single-quoted on the wire. */
declare function text(value: string): Expr<"text">;
/** Boolean literal — `Expr<"bool">`. Emits `TRUE()` / `FALSE()`. */
declare function bool(value: boolean): Expr<"bool">;
declare function plus<const A extends NumericLike | ExprLike<"date"> | ExprLike<"datetime">, const B extends NumericLike>(a: A, b: B): ComposedExpr<DateMathPromotion<A, B>, [A, B]>;
declare function minus<const A extends NumericLike | ExprLike<"date"> | ExprLike<"datetime">, const B extends NumericLike>(a: A, b: B): ComposedExpr<DateMathPromotion<A, B>, [A, B]>;
declare function times<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<NumericPromotion<A, B>, [A, B]>;
declare function dividedBy<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"decimal", [A, B]>;
type NonNumericComparableExprType = Exclude<ComparableExprType, "number" | "decimal">;
declare function gt<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function gt<T extends NonNumericComparableExprType, const A extends ExprLike<T>, const B extends ExprLike<NoInfer<T>>>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function lt<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function lt<T extends NonNumericComparableExprType, const A extends ExprLike<T>, const B extends ExprLike<NoInfer<T>>>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function gte<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function gte<T extends NonNumericComparableExprType, const A extends ExprLike<T>, const B extends ExprLike<NoInfer<T>>>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function lte<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function lte<T extends NonNumericComparableExprType, const A extends ExprLike<T>, const B extends ExprLike<NoInfer<T>>>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
type NonNumericExprType = Exclude<ExprType, "number" | "decimal">;
declare function eq<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function eq<T extends NonNumericExprType, const A extends ExprLike<T>, const B extends ExprLike<NoInfer<T>>>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function ne<const A extends NumericLike, const B extends NumericLike>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function ne<T extends NonNumericExprType, const A extends ExprLike<T>, const B extends ExprLike<NoInfer<T>>>(a: A, b: B): ComposedExpr<"bool", [A, B]>;
declare function and<const A extends BoolLike, const B extends BoolLike, const Rest extends readonly BoolLike[]>(a: A, b: B, ...rest: Rest): ComposedExpr<"bool", [A, B, ...Rest]>;
declare function or<const A extends BoolLike, const B extends BoolLike, const Rest extends readonly BoolLike[]>(a: A, b: B, ...rest: Rest): ComposedExpr<"bool", [A, B, ...Rest]>;
declare function if_<const Condition extends BoolLike, const Then extends NumericLike, const Else extends NumericLike>(cond: Condition, thenArm: Then, elseArm: Else): ComposedExpr<NumericPromotion<Then, Else>, [Condition, Then, Else]>;
declare function if_<T extends NonNumericExprType, const Condition extends BoolLike, const Then extends ExprLike<T>, const Else extends ExprLike<NoInfer<T>>>(cond: Condition, thenArm: Then, elseArm: Else): ComposedExpr<T, [Condition, Then, Else]>;
/**
 * Multi-branch conditional — `IFS(c1, v1, c2, v2, …)`.
 * Conditions are evaluated in order; the first one whose check
 * passes determines the result. If no condition matches, the result is null.
 *
 * Args must come in complete `(condition, value)` pairs, and all value arms
 * share the same result brand.
 *
 * Runtime validates parity — the EDK throws if an odd-then-even-
 * looking arg list slips past TS (e.g. when args is spread from an
 * untyped source).
 */
type IfsRest<T extends ExprType, Args extends readonly unknown[]> = Args extends readonly [] ? readonly [] : Args extends readonly [infer Condition, infer Value, ...infer Rest] ? readonly [
    Condition & BoolLike,
    Value & ExprLike<T>,
    ...IfsRest<T, Rest>
] : never;
declare function ifs<T extends ExprType, const Rest extends readonly unknown[]>(condition: BoolLike, value: ExprLike<T>, ...rest: Rest & IfsRest<NoInfer<T>, Rest>): ComposedExpr<T, [typeof condition, typeof value, ...Rest]>;
/**
 * True when the argument is null/empty. Accepts any expression type.
 * Equivalent to SQL `IS NULL` for non-text values; for text values
 * the server also treats whitespace-only strings as blank.
 */
declare function isBlank<T extends ExprType, const Value extends ExprLike<T>>(value: Value): ComposedExpr<"bool", [Value]>;
/**
 * Null literal — the wire `BLANK()` function. Returns an `Expr<T>`
 * whose brand is inferred from surrounding context (e.g. an
 * `if`/`ifs` arm). Standalone use requires an explicit type argument
 * (`calc.blank<"text">()`) because TS can't infer T from a
 * zero-argument call site.
 */
declare function blank<T extends ExprType>(type: T): Expr<T>;
declare function blank<T extends ExprType>(): Expr<T>;
/** Explicitly typed escape hatch for pulled and legacy formula text. */
declare function raw<T extends ExprType>(formula: string, resultType: T): Expr<T>;
type StoredFunctionArguments<Parameters extends readonly ExprType[]> = {
    readonly [Index in keyof Parameters]: Parameters[Index] extends ExprType ? ExprLike<Parameters[Index]> : never;
};
/** Invoke a configured scalar user-defined function from its CloudLink catalog ref. */
declare function call<const Parameters extends readonly StoredFunctionScalarType[], const Result extends StoredFunctionScalarType>(udf: StoredFunctionRef<Parameters, Result>, ...args: StoredFunctionArguments<Parameters>): Expr<Result, "single", "record">;
/**
 * Sum of a numeric expression across related rows. Server preserves
 * the input brand — `sum(NUMBER)` → NUMBER on the wire,
 * `sum(DECIMAL)` → DECIMAL. Overloads retain that exact brand for callers.
 */
declare function sum<const Value extends ExprLike<"number">>(value: Value): ComposedExpr<"number", [Value]>;
declare function sum<const Value extends ExprLike<"decimal">>(value: Value): ComposedExpr<"decimal", [Value]>;
/**
 * Count of non-null values for the argument expression across related
 * rows. Always returns `NUMBER` regardless of input brand.
 */
declare function count<T extends ExprType, const Value extends ExprLike<T>>(value: Value): ComposedExpr<"number", [Value]>;
/**
 * Distinct count of the argument expression across related rows.
 * Wire emits `COUNTUNIQUE` (matches the Java grammar's
 * `countDistinct` alias).
 */
declare function countUnique<T extends ExprType, const Value extends ExprLike<T>>(value: Value): ComposedExpr<"number", [Value]>;
/**
 * Arithmetic mean of a numeric expression across related rows.
 * Always returns `DECIMAL` (the server casts even integer fields to
 * decimal for division).
 */
declare function average<const Value extends NumericLike>(value: Value): ComposedExpr<"decimal", [Value]>;
/**
 * Standard deviation of a numeric expression across related rows.
 * Always returns `DECIMAL`.
 */
declare function stdev<const Value extends NumericLike>(value: Value): ComposedExpr<"decimal", [Value]>;
type MinMaxExprType = "number" | "decimal" | "date" | "datetime";
declare function min<const Value extends ExprLike<MinMaxExprType>>(value: Value): ComposedExpr<Extract<ExprTypeOf<Value>, MinMaxExprType>, [Value]>;
declare function min<const A extends ExprLike<MinMaxExprType>, const B extends ExprLike<Extract<ExprTypeOf<A>, MinMaxExprType>>, const Rest extends readonly ExprLike<Extract<ExprTypeOf<A>, MinMaxExprType>>[]>(a: A, b: B, ...rest: Rest): ComposedExpr<Extract<ExprTypeOf<A>, MinMaxExprType>, [A, B, ...Rest]>;
declare function max<const Value extends ExprLike<MinMaxExprType>>(value: Value): ComposedExpr<Extract<ExprTypeOf<Value>, MinMaxExprType>, [Value]>;
declare function max<const A extends ExprLike<MinMaxExprType>, const B extends ExprLike<Extract<ExprTypeOf<A>, MinMaxExprType>>, const Rest extends readonly ExprLike<Extract<ExprTypeOf<A>, MinMaxExprType>>[]>(a: A, b: B, ...rest: Rest): ComposedExpr<Extract<ExprTypeOf<A>, MinMaxExprType>, [A, B, ...Rest]>;
/** Project a picklist field reference to its display label (text). */
declare function label<const Field extends ExprLike<"picklist">>(field: Field): ComposedExpr<"text", [Field]>;
/** Project a reference-typed field to its id form (no-op for already-id refs). */
declare function id<T extends "picklist" | "user" | "group" | "attachment", const Field extends ExprLike<T>>(field: Field): ComposedExpr<T, [Field]>;
/** Project a user field reference to its email address (text). */
declare function email<const Field extends ExprLike<"user">>(field: Field): ComposedExpr<"text", [Field]>;
/** Project a group field reference to its name (text). */
declare function name<const Field extends ExprLike<"group">>(field: Field): ComposedExpr<"text", [Field]>;
/**
 * The `calc` namespace — every public builder lives here so authors
 * have one discoverable entry point. `calc.if` works because object
 * property names can be reserved words; only declarations like
 * `function if(){}` would conflict.
 */
